package com.example.bandlink.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="messages") public class Message { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private Conversation conversation; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User sender; @Column(columnDefinition="text") private String content; @Column(length=1000) private String imageUrl; @Column(nullable=false) private LocalDateTime createdAt; private LocalDateTime readAt; protected Message(){} public Message(Conversation c,User s,String content,String imageUrl,LocalDateTime now){conversation=c;sender=s;this.content=content;this.imageUrl=imageUrl;createdAt=now;} public Long getId(){return id;} public Conversation getConversation(){return conversation;} public User getSender(){return sender;} public String getContent(){return content;} public String getImageUrl(){return imageUrl;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getReadAt(){return readAt;} public void markRead(LocalDateTime now){readAt=now;} }
